import{_ as r,l as o,o as e,c as s,v as t,p as n,x as i,d as E,i as p,S as d}from"./chunks/framework.InCnrqk-.js";const D=JSON.parse('{"title":"放气","description":"","frontmatter":{"title":"放气","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/resist-outgassing.md","filePath":"litho/resist-outgassing.md","lastUpdated":1789023840000}'),h={name:"litho/resist-outgassing.md"};function A(c,a,B,_,u,m){const l=o("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="放气" tabindex="-1">放气 <a class="header-anchor" href="#放气" aria-label="Permalink to &quot;放气&quot;">​</a></h1><div class="epigraph"><p>真空里胶会吐分子；吐到多层膜上就是污染光学，灵敏度再好也过不了出气签核。</p><footer>—— 据 ASML 与抗蚀剂厂商对 EUV 胶放气 / 光学污染的公开讨论整理</footer></div><p><a href="/litho/euv-secondary-electron">上一课</a>把二次电子产额写成潜像核。缺口是同一套膜在真空扫描时还会挥发：碳氢与酸、配体碎片打到投影镜的 Mo/Si 多层膜上，反射率与 flare 一起坏。本课钉放气。随机缺孔留给[下一课](/litho/stochastic-holes），不在这里用平均 CD 代替缺陷尾。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>EUV 在真空中投影。CAR 的 PAG、淬灭剂、残留溶剂，锡氧胶的配体与小分子，底层的挥发分，都会在曝光与烘烤后继续出气。DUV 浸没有镜头最后表面与水的污染账；EUV 换成多层膜与膜（pellicle）的碳污染、氧化。ASML 公开把抗蚀剂出气资格当作上机条件：不是实验室对比度够就能进 NXE。</p><p>缺口不是再提高产额，而是卫生。把「更敏」写成无条件目标，会选出出气最凶的配方。把污染全部写成光源锡屑，会漏掉晶圆侧的碳氢。</p><h3 id="出气资格不是灵敏度曲线" tabindex="-1">出气资格不是灵敏度曲线 <a class="header-anchor" href="#出气资格不是灵敏度曲线" aria-label="Permalink to &quot;出气资格不是灵敏度曲线&quot;">​</a></h3><p>公开流程用见证片（witness sample）一类方法看膜层反射率损失或碳生长，再决定这支胶能不能进量产腔。数字与规程是厂商与用户合同，本课不编阈值、不编小时数。要记住的是：签核对象是光学寿命，不是 CD。</p><p><span class="marginnote">氢环境可以清一部分碳，却也带来膜与胶的其他化学。出气合格不等于「可以随便加剂量」。剂量高，曝光时间长，同一挥发速率下积分污染更大——与产能会计同一条时间轴。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>栈一起管：胶、底层、面涂（若有）、烘烤把溶剂赶掉的程度。底层课已经说过它可以当阻挡，也可以自己成为源。换胶族必须重做出气，不能假设锡氧比 CAR 更干净或更脏——配体挥发与有机 PAG 是不同物种。轨道上的后烘、延迟时间改变残留溶剂，出气指纹会变。</p><p>机台侧：气流、温度、氢清洗、pellicle 是否挡住一部分物种。这些是设备课，本课只要求胶的出气数据与机台资格匹配，而不是只报 RLS。</p><h3 id="与成像正交、与窗口相关" tabindex="-1">与成像正交、与窗口相关 <a class="header-anchor" href="#与成像正交、与窗口相关" aria-label="Permalink to &quot;与成像正交、与窗口相关&quot;">​</a></h3><p>出气不直接改 TCC。它改长期 flare 与反射率，从而慢慢改剂量到达和对比。短期则是资格门槛：过不了门，再好的 NILS 也印不成。CD 窗签核必须附带「这支胶已出气合格」，否则工艺窗是实验室窗。</p>',14)),(e(),n(d,null,{default:i(()=>[p(l,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20RES%5B%22%E8%83%B6%20%2F%20%E5%BA%95%E5%B1%82%E6%8C%A5%E5%8F%91%E5%88%86%22%5D%20--%3E%20VAC%5B%22EUV%20%E7%9C%9F%E7%A9%BA%22%5D%0A%20%20VAC%20--%3E%20ML%5B%22%E5%A4%9A%E5%B1%82%E8%86%9C%E7%A2%B3%E6%B1%A1%E6%9F%93%22%5D%0A%20%20ML%20--%3E%20R%5B%22%E5%8F%8D%E5%B0%84%E7%8E%87%20%2F%20flare%22%5D%0A%20%20QUAL%5B%22%E5%87%BA%E6%B0%94%E8%B5%84%E6%A0%BC%22%5D%20--%3E%20TOOL%5B%22%E8%83%BD%E5%90%A6%E4%B8%8A%E6%9C%BA%22%5D%0A%20%20SE%5B%22%E4%B8%8A%E4%B8%80%E8%AF%BE%3A%20%E7%94%B5%E5%AD%90%E4%BA%A7%E9%A2%9D%22%5D%20--%3E%20LAT%5B%22%E6%BD%9C%E5%83%8F%22%5D%0A%20%20LAT%20--%3E%20QUAL%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>曝光打断键，小分子从自由体积里扩散到真空。EUV 每次吸收能量高，碎片通道比 DUV 光解更杂。物种落到多层膜上，改变周期膜的光学厚度与吸收，局部反射率下降，散射上升，像面台基（flare）抬高——暗区剂量上升，化学上又去打淬灭剂库存。于是卫生失败会回头变成成像失败，只是时间尺度是镜片寿命，不是单场。</p><p>锡氧胶的无机骨架本身不易挥发，配体和溶剂仍会。CAR 的酸与淬灭剂是已知的 DUV 污染源，在真空里同样在场。公开讨论把「低出气」写成与灵敏度并列的配方约束，而不是验收之后的环保附录。</p><p><span class="marginnote">计量胶、BARC、底部抗反射在 DUV 轨道上的出气经验，不能直接当 EUV 多层膜合同。真空、氢、13.5 nm 光学是另一套材料兼容表。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不写见证片的具体纳米碳厚规格，不编某型号镜片的寿命小时。不把光源 tin debris 与胶放气合成一个「污染」桶——锡屑是光源课，碳氢是本课。随机缺失下一课才成为良率墙；出气合格的胶仍可以因光子稀疏而缺孔。</p><p>DUV 193 nm 镜头出气/浸出已在面涂课；本课对象是 EUV 真空光学。不要把浸没 leaching 的水分析仪方法原样搬来当 EUV 资格。二次电子产额再高，也买不走出气门：上一课的灵敏度与本课的卫生是两条签核，缺一不可。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>EUV 胶与底层的挥发分污染多层膜；出气资格是上机门槛。</li><li>更敏若换来更凶的出气，不是净收益；剂量积分放大污染。</li><li>底层可挡可源；换胶族必须重做资格。</li><li>污染抬 flare，长期会回头改成像，短期则是能不能进腔。</li><li>缺孔统计下一课；本课不代替随机尾。</li><li>灵敏度与出气资格是两条签核，缺一不可。</li><li>出处：ASML 对 EUV 抗蚀剂出气与光学污染的公开要求；胶栈公开讨论。</li></ul>',9))])}const V=r(h,[["render",A]]);export{D as __pageData,V as default};
